function validate([nums, k, p]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 200) return 'nums needs 1 to 200 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 200)) return 'Each value of nums is an integer from 1 to 200.';
  if (!Number.isInteger(p) || p < 1 || p > 200) return 'p is an integer from 1 to 200.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is an integer from 1 to nums.length.';
  return null;
}

