function countDistinct(nums, k, p) {
  const seen = new Set();

  for (let start = 0; start < nums.length; start++) {
    let divisible = 0;
    let key = '';
    for (let end = start; end < nums.length; end++) {
      if (nums[end] % p === 0) {
        divisible++;
      }
      if (divisible > k) {
        break;
      }
      key += nums[end] + ',';
      seen.add(key);
    }
  }
  return seen.size;
}

