function countDistinct(nums, k, p) {
  const kept = [];
  for (let i = 0; i < nums.length; i++) {
    for (let j = i; j < nums.length; j++) {
      const part = nums.slice(i, j + 1);
      if (part.filter(v => v % p === 0).length > k) continue;
      const duplicate = kept.some(other => other.length === part.length && other.every((v, idx) => v === part[idx]));
      if (!duplicate) kept.push(part);
    }
  }
  return kept.length;
}

