function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = pick(180, 200);
    const top = rand() < 0.5 ? pick(2, 6) : 200;
    const nums = Array.from({ length: n }, () => pick(1, top));
    const p = rand() < 0.7 ? pick(1, 6) : pick(1, 200);
    const k = rand() < 0.5 ? pick(1, 10) : pick(1, n);
    return [nums, k, p];
  }
  const n = pick(1, 9);
  const nums = Array.from({ length: n }, () => pick(1, 6));
  return [nums, pick(1, n), pick(1, 4)];
}
